import React from 'react';
import '../styles/main.css';
import PortfolioItem from './PortfolioItem';

const portfolioData = [
  {
    title: "Project One",
    description: "Short description of project one.",
    image: "https://via.placeholder.com/300x200"
  },
  {
    title: "Project Two",
    description: "Short description of project two.",
    image: "https://via.placeholder.com/300x200"
  }
  // Add more projects as needed
];

const techTools = [
  { name: "React", icon: "⚛️" },
  { name: "Bootstrap", icon: "🅱️" },
  { name: "Postman", icon: "📬" },
  { name: "Figma", icon: "🎨" },
  { name: "Git", icon: "🔧" },
  { name: "Vercel", icon: "▲" }
];

const softSkills = [
  "Communication",
  "Team Work",
  "Problem Solving"
];

function Header() {
  return (
    <div>
      {/* Hero Section */}
      <header>
        <div className="container">
          <h1>Adigun Sheriff</h1>
          <p className="welcome-message">Frontend Developer | Designer</p>
        </div>
      </header>

      {/* About Section */}
      <section className="container">
        <h2>About Me</h2>
        <p>
          I am a passionate frontend developer and designer with experience building responsive web applications and user interfaces. I enjoy solving problems and collaborating with teams to deliver high-quality products.
        </p>
      </section>

      {/* Technologies & Tools Section */}
      <section className="container">
        <h2>Technologies & Tools</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '16px', marginBottom: '10px' }}>
          {techTools.map((tool, idx) => (
            <div key={idx} style={{
              background: '#f4f6f8',
              border: '1px solid #e1e1e1',
              borderRadius: '5px',
              padding: '10px 18px',
              fontSize: '1.1rem',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}>
              <span>{tool.icon}</span>
              <span>{tool.name}</span>
            </div>
          ))}
        </div>
      </section>

      {/* Projects Section */}
      <section className="container">
        <h2>Projects</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
          {portfolioData.map((item, idx) => (
            <PortfolioItem key={idx} {...item} />
          ))}
        </div>
      </section>

      {/* Soft Skills Section */}
      <section className="container">
        <h2>Soft Skills</h2>
        <ul style={{ fontSize: '1.08rem', color: '#555', paddingLeft: '18px' }}>
          {softSkills.map((skill, idx) => (
            <li key={idx}>{skill}</li>
          ))}
        </ul>
      </section>

      {/* Footer */}
      <footer>
        <div className="container">
          <div style={{ marginBottom: '8px' }}>
            <strong>Adigun Sheriff</strong> | Frontend Developer & Designer
          </div>
          <div style={{ marginBottom: '8px' }}>
            Email: <a href="mailto:your.email@example.com" style={{ color: '#ffd700' }}>your.email@example.com</a>
          </div>
          <div>
            <a href="https://github.com/" target="_blank" rel="noopener noreferrer" style={{ color: '#ffd700', marginRight: '12px' }}>GitHub</a>
            <a href="https://linkedin.com/" target="_blank" rel="noopener noreferrer" style={{ color: '#ffd700', marginRight: '12px' }}>LinkedIn</a>
            <a href="https://twitter.com/" target="_blank" rel="noopener noreferrer" style={{ color: '#ffd700' }}>Twitter</a>
          </div>
          <div style={{ marginTop: '8px' }}>
            &copy; {new Date().getFullYear()} Adigun Sheriff. All rights reserved.
          </div>
        </div>
      </footer>
    </div>
  );
}

export default Header;
